-- Coordinated cutover: stop app and worker, retain backup and restore as recovery.
-- Configuration starts empty; no approved clinical process, real shift or occupancy is fabricated.
CREATE OR REPLACE FUNCTION cvg_runtime_entity_collections() RETURNS text[]
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
 SELECT ARRAY['savedPlannerViews','hospitalTaskTypes','hospitalTasks','hospitalTaskDependencies','hospitalIntakes','hospitalServices','hospitalResources','hospitalPlans','hospitalShifts','hospitalHandoffs','hospitalChecklistTemplates','hospitalRecurrences','examDefinitions','accessGroups','patientGrants','departments','users','sessions','patients','encounters','admissions','services','reasonCodes','requests','items','samples','procedures','schedules','results','resultVersions','notifications','idempotency','attachments']::text[]
$$;
CREATE UNIQUE INDEX cvg_hospital_resource_code_unique ON cvg_runtime_entities ((data->>'code')) WHERE collection='hospitalResources';
CREATE UNIQUE INDEX cvg_hospital_professional_resource_unique ON cvg_runtime_entities ((data->>'userId')) WHERE collection='hospitalResources' AND data->>'kind'='PROFESSIONAL';
CREATE UNIQUE INDEX cvg_hospital_plan_code_unique ON cvg_runtime_entities ((data->>'code')) WHERE collection='hospitalPlans';
CREATE UNIQUE INDEX cvg_hospital_shift_code_unique ON cvg_runtime_entities ((data->>'code')) WHERE collection='hospitalShifts';
CREATE UNIQUE INDEX cvg_hospital_checklist_code_unique ON cvg_runtime_entities ((data->>'code')) WHERE collection='hospitalChecklistTemplates';
CREATE UNIQUE INDEX cvg_hospital_recurrence_occurrence_unique ON cvg_runtime_entities ((data->>'recurrenceId'),(data->>'occurrenceAt')) WHERE collection='hospitalTasks' AND data ? 'recurrenceId' AND data ? 'occurrenceAt';
