","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect","procedure.schedule","procedure.reschedule","procedure.start","procedure.mark_performed","result.draft.create","result.draft.edit_own","result.release","result.amend","result.void","attachment.download","attachment.upload_session","attachment.finalize","notification.acknowledge"],"VIEWER":["plan.view","shift.view","checklist_template.view","recurrence.view","hospital_resource.view","hospital_calendar.view","hospital_capacity.view","planner_view.view","planner_view.create","planner_view.update","planner_view.deactivate","hospital_task.view","hospital_intake.view","department.view","patient.view","encounter.view","admission.view","request.view","request.list","item.view","result.view","result.history.view","result.view.record","attachment.view","notification.view","diagnostic.timeline.view","timeline.view","search.execute","queue.view","dashboard.view","service.catalog.view","realtime.connect"]}'::jsonb;
 affected_groups text[];
 group_count integer;
BEGIN
 SELECT version INTO current_version FROM cvg_runtime_state WHERE id=1 FOR UPDATE;
 IF current_version IS NOT NULL THEN
  -- A customized matrix retains every chosen restriction, including reduced system profiles.
  WITH changed AS (
   UPDATE cvg_runtime_entities SET data=data || jsonb_build_object('permissions',target_defaults->(data->>'systemRole'),
    'version',(data->>'version')::integer+1,'updatedAt',timestamp_text),written_version=current_version+1
   WHERE collection='accessGroups' AND previous_defaults ? (data->>'systemRole')
    AND (data->'permissions') @> (previous_defaults->(data->>'systemRole'))
    AND (previous_defaults->(data->>'systemRole')) @> (data->'permissions')
   RETURNING entity_key
  ) SELECT array_agg(entity_key),count(*) INTO affected_groups,group_count FROM changed;
  UPDATE cvg_runtime_entities SET data=data || jsonb_build_object('version',(data->>'version')::integer+1),written_version=current_version+1
   WHERE collection='users' AND data->>'accessGroupId'=ANY(affected_groups);
  UPDATE cvg_runtime_entities AS session SET data=session.data || jsonb_build_object('revokedAt',timestamp_text,'version',(session.data->>'version')::integer+1),written_version=current_version+1
   WHERE session.collection='sessions' AND NOT session.data ? 'revokedAt' AND EXISTS(SELECT 1 FROM cvg_runtime_entities AS target
    WHERE target.collection='users' AND target.data->>'id'=session.data->>'userId' AND target.data->>'accessGroupId'=ANY(affected_groups));
  UPDATE cvg_runtime_state SET state=cvg_runtime_state_header(state),version=current_version+1,updated_at=now() WHERE id=1;
  INSERT INTO audit_events(id,event_type,entity_type,entity_id,correlation_id,metadata,occurred_at)
   VALUES('audit-migration-024','HospitalPlanningResourcesEnabled','SchemaMigration','024_hospital_planning_resources','corr-migration-024',
    jsonb_build_object('systemGroupsUpdated',group_count,'clinicalScopeChanged',false,'reservationsFabricated',false,'approvedProcessesFabricated',false),CURRENT_TIMESTAMP);
 END IF;
END $$;
ALTER TABLE cvg_runtime_state ADD CONSTRAINT runtime_hospital_planning_resources_are_external CHECK(state->'hospitalResources'='[]'::jsonb AND state->'hospitalPlans'='[]'::jsonb AND state->'hospitalShifts'='[]'::jsonb AND state->'hospitalHandoffs'='[]'::jsonb AND state->'hospitalChecklistTemplates'='[]'::jsonb AND state->'hospitalRecurrences'='[]'::jsonb);
UPDATE relational_schema_markers SET schema_version='024_hospital_planning_resources' WHERE marker_key='RELATIONAL_CLINICAL_CORE_EXPAND_V1';
